23: namespace SonarAnalyzer.Rules
24: {
25:     public abstract class UriShouldNotBeHardcodedBase<TSyntaxKind, TLiteralExpressionSyntax, TArgumentSyntax> : SonarDiagnosticAnalyzer<TSyntaxKind>
26:         where TSyntaxKind : struct
27:         where TLiteralExpressionSyntax : SyntaxNode
28:         where TArgumentSyntax : SyntaxNode
29:     {
30:         protected const string DiagnosticId = "S1075";
31: 
32:         protected const string AbsoluteUriMessage = "Refactor your code not to use hardcoded absolute paths or URIs.";
33:         protected const string PathDelimiterMessage = "Remove this hardcoded path-delimiter.";
34: 
35:         // Simplified implementation of specification listed on
36:         // https://en.wikipedia.org/wiki/Uniform_Resource_Identifier
37:         private const string UriScheme = "^[a-zA-Z][a-zA-Z\\+\\.\\-]+://.+";
38: 
39:         private const string AbsoluteDiskUri = @"^[A-Za-z]:(/|\\)";
40:         private const string AbsoluteMappedDiskUri = @"^\\\\\w[ \w\.]*";
41: 
42:         protected static readonly Regex UriRegex = new($"{UriScheme}|{AbsoluteDiskUri}|{AbsoluteMappedDiskUri}", RegexOptions.Compiled, TimeSpan.FromSeconds(1));
43: 
44:         protected static readonly Regex PathDelimiterRegex = new(@"^(\\|/)$", RegexOptions.Compiled, TimeSpan.FromSeconds(1));
45: 
46:         protected static readonly ISet<string> CheckedVariableNames =
47:             new HashSet<string>
48:             {
49:                 "FILE",
50:                 "PATH",
51:                 "URI",
52:                 "URL",
53:                 "URN",
54:                 "STREAM"
55:             };
56: 
57:         protected override string MessageFormat => "{0}";
58: 
59:         protected UriShouldNotBeHardcodedBase() : base(DiagnosticId) { }
60: 
61:         protected abstract GeneratedCodeRecognizer GeneratedCodeRecognizer { get; }
62:         protected abstract TSyntaxKind[] StringConcatenateExpressions { get; }
63:         protected abstract TSyntaxKind[] InvocationOrObjectCreationKind { get; }
64:         protected abstract SyntaxNode GetRelevantAncestor(SyntaxNode node);
65: 
66:         protected override void Initialize(SonarAnalysisContext context)
67:         {
68:             context.RegisterNodeAction(
69:                 GeneratedCodeRecognizer,
70:                 c =>
71:                 {
72:                     if (UriRegex.IsMatch(Language.Syntax.LiteralText(c.Node)) && IsInCheckedContext(c.Node, c.SemanticModel))
73:                     {
74:                         c.ReportIssue(Diagnostic.Create(SupportedDiagnostics[0], c.Node.GetLocation(), AbsoluteUriMessage));
75:                     }
76:                 },
77:                 Language.SyntaxKind.StringLiteralExpressions);
78: 
79:             context.RegisterNodeAction(
80:                 GeneratedCodeRecognizer,
81:                 c =>
82:                 {
83:                     var isInCheckedContext = new Lazy<bool>(() => IsInCheckedContext(c.Node, c.SemanticModel));
84: 
85:                     var leftNode = Language.Syntax.BinaryExpressionLeft(c.Node);
86:                     if (IsPathDelimiter(leftNode) && isInCheckedContext.Value)
87:                     {
88:                         c.ReportIssue(Diagnostic.Create(SupportedDiagnostics[0], leftNode.GetLocation(), PathDelimiterMessage));
89:                     }
90: 
91:                     var rightNode = Language.Syntax.BinaryExpressionRight(c.Node);
92:                     if (IsPathDelimiter(rightNode) && isInCheckedContext.Value)
93:                     {
94:                         c.ReportIssue(Diagnostic.Create(SupportedDiagnostics[0], rightNode.GetLocation(), PathDelimiterMessage));
95:                     }
96:                 },
97:                 StringConcatenateExpressions);
98:         }
99: 
100:         private bool IsInCheckedContext(SyntaxNode expression, SemanticModel model)
101:         {
102:             var argument = expression.FirstAncestorOrSelf<TArgumentSyntax>();
103:             if (argument != null)
104:             {
105:                 var argumentIndex = Language.Syntax.ArgumentIndex(argument);
106:                 if (argumentIndex is null or < 0)
107:                 {
108:                     return false;
109:                 }
110: 
111:                 var constructorOrMethod = argument.Ancestors().FirstOrDefault(x => Language.Syntax.IsAnyKind(x, InvocationOrObjectCreationKind));
112:                 var methodSymbol = constructorOrMethod != null
113:                     ? model.GetSymbolInfo(constructorOrMethod).Symbol as IMethodSymbol
114:                     : null;
115: 
116:                 return methodSymbol != null
117:                        && argumentIndex.Value < methodSymbol.Parameters.Length
118:                        && methodSymbol.Parameters[argumentIndex.Value].Name.SplitCamelCaseToWords().Any(CheckedVariableNames.Contains);
119:             }
120: 
121:             return GetRelevantAncestor(expression) is { } relevantAncestor && Language.GetName(relevantAncestor).SplitCamelCaseToWords().Any(CheckedVariableNames.Contains);
122:         }
123: 
124:         private bool IsPathDelimiter(SyntaxNode expression) =>
125:             expression is TLiteralExpressionSyntax && PathDelimiterRegex.IsMatch(Language.Syntax.LiteralText(expression));
126:     }
127: }
